using System;
using System.Collections.Generic;
using System.Linq;

public static class Temps
{
    public static double CToF(double c) => Math.Round(c * 9 / 5 + 32, 1);

    public static double FToC(double f) => Math.Round((f - 32) * 5 / 9, 1);
}

