using System;
using System.Collections.Generic;
using System.Linq;

public static class Price
{
    public static double Total(int qty, double unitPrice, double discountPercent = 0)
    {
        if (discountPercent < 0 || discountPercent > 100) throw new ArgumentException("bad discount");
        return Math.Round(qty * unitPrice * (100 - discountPercent) / 100, 2);
    }
}
